/* ============================================
   DRAWER COMPONENT
   Edge-anchored panel, modal by default, that slides in
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-drawer {
  position: fixed;
  inset: 0;
  z-index: var(--layer-modal);
  display: flex;
  visibility: hidden; /* keeps panel controls out of the tab order when closed */
  pointer-events: none;
  transition: visibility var(--motion-duration-slow) var(--motion-ease-standard);
  /* How far the closed panel rests off its edge: its own size, plus the
     float gap when it is held off the edge. */
  --ds-drawer-offset: 100%;
}

.ds-drawer--open {
  visibility: visible;
  pointer-events: auto;
}

/* Anchor the panel to the requested edge. `left` and `right` name screen
   edges, so in a right-to-left page (where flex-start is the right) they
   swap their flex ends to stay put; `start` and `end` follow the reading
   direction. */
.ds-drawer--left,
.ds-drawer--start {
  justify-content: flex-start;
  align-items: stretch;
}

.ds-drawer--right,
.ds-drawer--end {
  justify-content: flex-end;
  align-items: stretch;
}

.ds-drawer--left:dir(rtl) {
  justify-content: flex-end;
}

.ds-drawer--right:dir(rtl) {
  justify-content: flex-start;
}

.ds-drawer--top {
  align-items: flex-start;
  justify-content: stretch;
}

.ds-drawer--bottom {
  align-items: flex-end;
  justify-content: stretch;
}

/* ============================================
   SCRIM
   ============================================ */

.ds-drawer__scrim {
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
  opacity: 0;
  transition: opacity var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-drawer--open .ds-drawer__scrim {
  opacity: 1;
}

/* ============================================
   PANEL
   ============================================ */

.ds-drawer__panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: var(--gap-400); /* 16px */
  padding: var(--padding-500); /* 20px */
  background-color: var(--color-bg-page-primary);
  box-shadow: var(--shadow-modal);
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
  outline: none;
  overflow: hidden;
}

/* Edge-specific border + resting (off-screen) transform. The left and
   right drawers' sides are the screen's; the start and end drawers' are the
   reading direction's, so their slide follows the direction sign
   (src/behaviors/direction.css). */
.ds-drawer--left .ds-drawer__panel {
  height: 100%;
  border-right: var(--border-025) solid var(--color-bg-container-border); /* ds-allow(physical): a left drawer sits on the screen's left edge */
  transform: translateX(calc(-1 * var(--ds-drawer-offset))); /* ds-allow(physical): it slides in from the screen's left edge */
}

.ds-drawer--right .ds-drawer__panel {
  height: 100%;
  border-left: var(--border-025) solid var(--color-bg-container-border); /* ds-allow(physical): a right drawer sits on the screen's right edge */
  transform: translateX(var(--ds-drawer-offset)); /* ds-allow(physical): it slides in from the screen's right edge */
}

.ds-drawer--start .ds-drawer__panel {
  height: 100%;
  border-inline-end: var(--border-025) solid var(--color-bg-container-border);
  transform: translateX(calc(-1 * var(--ds-drawer-offset) * var(--ds-inline-sign, 1)));
}

.ds-drawer--end .ds-drawer__panel {
  height: 100%;
  border-inline-start: var(--border-025) solid var(--color-bg-container-border);
  transform: translateX(calc(var(--ds-drawer-offset) * var(--ds-inline-sign, 1)));
}

.ds-drawer--top .ds-drawer__panel {
  width: 100%;
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
  transform: translateY(calc(-1 * var(--ds-drawer-offset)));
}

.ds-drawer--bottom .ds-drawer__panel {
  width: 100%;
  border-top: var(--border-025) solid var(--color-bg-container-border);
  transform: translateY(var(--ds-drawer-offset));
}

.ds-drawer--open .ds-drawer__panel {
  transform: translate(0, 0);
}

/* ============================================
   NON-MODAL
   The page beside the panel stays live: the
   root lets every press through and only the
   panel takes them. No scrim is rendered.
   ============================================ */

.ds-drawer--non-modal.ds-drawer--open {
  pointer-events: none;
}

.ds-drawer--non-modal.ds-drawer--open .ds-drawer__panel {
  pointer-events: auto;
}

/* ============================================
   SIZES — measured along the slide axis
   ============================================ */

.ds-drawer--left.ds-drawer--sm .ds-drawer__panel,
.ds-drawer--right.ds-drawer--sm .ds-drawer__panel,
.ds-drawer--start.ds-drawer--sm .ds-drawer__panel,
.ds-drawer--end.ds-drawer--sm .ds-drawer__panel {
  width: 320px;
  max-width: 100vw;
}

.ds-drawer--left.ds-drawer--md .ds-drawer__panel,
.ds-drawer--right.ds-drawer--md .ds-drawer__panel,
.ds-drawer--start.ds-drawer--md .ds-drawer__panel,
.ds-drawer--end.ds-drawer--md .ds-drawer__panel {
  width: 420px;
  max-width: 100vw;
}

.ds-drawer--left.ds-drawer--lg .ds-drawer__panel,
.ds-drawer--right.ds-drawer--lg .ds-drawer__panel,
.ds-drawer--start.ds-drawer--lg .ds-drawer__panel,
.ds-drawer--end.ds-drawer--lg .ds-drawer__panel {
  width: 560px;
  max-width: 100vw;
}

.ds-drawer--top.ds-drawer--sm .ds-drawer__panel,
.ds-drawer--bottom.ds-drawer--sm .ds-drawer__panel {
  max-height: 30vh;
}

.ds-drawer--top.ds-drawer--md .ds-drawer__panel,
.ds-drawer--bottom.ds-drawer--md .ds-drawer__panel {
  max-height: 50vh;
}

.ds-drawer--top.ds-drawer--lg .ds-drawer__panel,
.ds-drawer--bottom.ds-drawer--lg .ds-drawer__panel {
  max-height: 75vh;
}

/* ============================================
   FLOATING
   The raised edge of the floating app shell
   (src/behaviors/shell.css): held off every
   edge by the float gap, a hairline all round,
   the shell radius and the floating shadow.
   After SIZES, so its width cap outranks theirs;
   border-box, so a size is the whole card and
   the card fits inside the gap.
   ============================================ */

.ds-drawer--floating {
  padding: var(--padding-500); /* 20px, the same step as the shell's float gap */
  --ds-drawer-offset: calc(100% + var(--padding-500));
}

.ds-drawer.ds-drawer--floating .ds-drawer__panel {
  box-sizing: border-box;
  max-width: 100%;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  box-shadow: var(--shadow-floating);
}

/* ============================================
   HEADER
   ============================================ */

.ds-drawer__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--gap-400); /* 16px */
  flex-shrink: 0;
}

.ds-drawer__heading {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100); /* 4px */
  min-width: 0;
}

.ds-drawer__title {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-heading);
  margin: 0;
}

.ds-drawer__description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  margin: 0;
}

/* Close button — ghost icon button */
/* The close is the library's IconButton (tertiary, compact); the
   header only seats it. */
.ds-drawer__close {
  flex-shrink: 0;
}

/* ============================================
   BODY
   ============================================ */

.ds-drawer__body {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   FOOTER
   ============================================ */

.ds-drawer__footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--gap-200); /* 8px */
  padding-top: var(--padding-150); /* 6px */
  flex-shrink: 0;
}

/* ============================================
   RESPONSIVE
   Side drawers go full-width on narrow screens
   ============================================ */

@media (max-width: 480px) {
  .ds-drawer--left .ds-drawer__panel,
  .ds-drawer--right .ds-drawer__panel {
    width: 100vw;
  }
}

/* ============================================
   REDUCED MOTION
   ============================================ */

/* ds-allow(motion): drops the slide and the scrim fade outright rather than playing them at 0.01ms. */
@media (prefers-reduced-motion: reduce) {
  .ds-drawer,
  .ds-drawer__panel,
  .ds-drawer__scrim {
    transition: none;
  }
}

} /* @layer rift.components */

'use client';

import React, { useRef, useId } from 'react';
import { IconButton } from '../IconButton/IconButton';
import ReactDOM from 'react-dom';
import './Drawer.css';
import '../../behaviors/direction.css';
import '../../behaviors/visually-hidden.css';
import '../../fonts/material-symbols.css';
import { useMounted } from '../../behaviors/useMounted';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';

/** Props owned by Drawer itself — everything else falls through to the panel. */
type DrawerOwnProps = {
  /** Whether the drawer is open */
  open: boolean;
  /** Callback when the drawer requests to close */
  onOpenChange: (open: boolean) => void;
  /**
   * Drawer title.
   * Note: this shadows the native `title` tooltip attribute, which Drawer does not expose.
   */
  title: string;
  /** Optional subtitle under the title */
  description?: string;
  /**
   * Content shown in place of the title text, such as a site's logo. The
   * `title` still names the dialog, read by assistive tech from a visually
   * hidden heading.
   */
  heading?: React.ReactNode;
  /** Drawer body content */
  children?: React.ReactNode;
  /** Optional footer slot — typically a row of Buttons */
  footer?: React.ReactNode;
  /**
   * Edge the panel slides in from. `left` and `right` are the screen's
   * edges in any reading direction; `start` and `end` follow it, so a
   * `start` drawer opens on the left in English and on the right in Arabic.
   */
  side?: 'left' | 'right' | 'start' | 'end' | 'top' | 'bottom';
  /** Panel size along the axis it slides on */
  size?: 'sm' | 'md' | 'lg';
  /** Whether ESC, scrim click, and the close button can dismiss */
  dismissible?: boolean;
  /**
   * Whether the drawer takes over the page. `true` (the default) draws the
   * scrim, traps focus, locks scroll and makes the page behind inert. `false`
   * leaves the page live beside the panel, for a detail view that follows a
   * list: no scrim, no trap, and a press outside never closes it. Focus still
   * moves into the panel on open; on close it returns to the opener only if
   * it is still inside the panel.
   */
  modal?: boolean;
  /**
   * How the panel meets the edge. `flush` (the default) runs to the edge with
   * a hairline on the side facing the page; `floating` holds the panel off
   * every edge as a raised, rounded card.
   */
  layout?: 'flush' | 'floating';
  /** Accessible name of the close button. */
  closeLabel?: string;
  /** Additional CSS classes — applied to the portal container, not the panel */
  className?: string;
};

export interface DrawerProps
  extends DrawerOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof DrawerOwnProps> {}

/**
 * Drawer component — an edge-anchored panel that slides in over the page.
 * Shares Dialog's modal semantics (focus trap, focus restore, scroll lock,
 * ESC/scrim dismissal) but is anchored to a viewport edge, which suits
 * filter panels, detail views, and mobile navigation. With `modal={false}`
 * it rests beside a page that stays live.
 *
 * Renders through a portal into `document.body`. The forwarded ref and any
 * unrecognised props target the **panel** (the `role="dialog"` element), not the
 * portal container.
 */
export const Drawer = React.forwardRef<HTMLDivElement, DrawerProps>(
  (
    {
      open,
      onOpenChange,
      title,
      description,
      heading,
      children,
      footer,
      side = 'right',
      size = 'md',
      dismissible = true,
      modal = true,
      layout = 'flush',
      closeLabel = 'Close drawer',
      className = '',
      ...rest
    },
    ref,
  ) => {
    const panelRef = useRef<HTMLDivElement | null>(null);
    const titleId = useId();
    const descId = useId();
    const baseClass = 'ds-drawer';

    /** Keep the internal ref (used by the focus trap) while honouring a forwarded one. */
    const setPanelRef = (node: HTMLDivElement | null) => {
      panelRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    // SSR guard — only render the portal on the client
    const mounted = useMounted();

    // Shared overlay behaviors (src/behaviors/) — see Dialog for the
    // contract. Scrim dismissal stays below: it is this component's own DOM.
    // A non-modal drawer never owns a press, so it sits on the stack as a
    // passive layer: Escape still reaches it, and a press on the live page
    // beside it passes through to whatever is open beneath.
    const layer = useLayer({
      open,
      dismissOnEscape: dismissible,
      onDismiss: () => onOpenChange(false),
      passive: !modal,
      getElements: modal ? undefined : () => [panelRef.current],
    });
    useFocusScope(panelRef, {
      active: open,
      trap: modal,
      inertOutside: modal,
      // The page stays live beside a non-modal drawer, so by the time it
      // closes focus may already be where the reader put it. Only a focus
      // still inside the panel goes back to the opener.
      restoreFocus: modal
        ? true
        : () => {
            const active = document.activeElement;
            if (!(active instanceof HTMLElement) || active === document.body) return null;
            return panelRef.current?.contains(active) ? null : active;
          },
    });
    useScrollLock(open && modal);

    // A press that began while a menu or popover was open above this layer was
    // that layer's press: it closed the menu, and must not also close this.
    const handleScrimClick = () => {
      if (dismissible && layer.ownsPress()) onOpenChange(false);
    };

    const classes = [
      baseClass,
      `${baseClass}--${side}`,
      `${baseClass}--${size}`,
      layout === 'floating' ? `${baseClass}--floating` : '',
      modal ? '' : `${baseClass}--non-modal`,
      open ? `${baseClass}--open` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const drawer = (
      <div className={classes} data-state={open ? 'open' : 'closed'}>
        {modal && <div className={`${baseClass}__scrim`} onClick={handleScrimClick} />}

        {/* data-state is the open state as an attribute, for a consumer's
            styles and tests; the drawer stays mounted so it can slide shut,
            so its presence in the DOM never means it is open. */}
        <div
          {...rest}
          className={`${baseClass}__panel`}
          data-state={open ? 'open' : 'closed'}
          ref={setPanelRef}
          role="dialog"
          aria-modal={modal ? 'true' : undefined}
          aria-labelledby={titleId}
          aria-describedby={description ? descId : rest['aria-describedby']}
          tabIndex={-1}
        >
          <div className={`${baseClass}__header`}>
            <div className={`${baseClass}__heading`}>
              <h2
                className={heading ? 'ds-visually-hidden' : `${baseClass}__title`}
                id={titleId}
              >
                {title}
              </h2>
              {heading}
              {description && (
                <p className={`${baseClass}__description`} id={descId}>
                  {description}
                </p>
              )}
            </div>

            {dismissible && (
              <IconButton
                className={`${baseClass}__close`}
                icon="close"
                variant="tertiary"
                size="compact"
                tooltip={false}
                label={closeLabel}
                onClick={() => onOpenChange(false)}
              />
            )}
          </div>

          {children && (
            // Scrollable when content is long; without a tab stop a keyboard
            // user cannot reach that scroll. The initial-focus query below
            // still prefers a real control, so this does not steal focus.
            <div className={`${baseClass}__body`} tabIndex={0}>
              {children}
            </div>
          )}

          {footer && <div className={`${baseClass}__footer`}>{footer}</div>}
        </div>
      </div>
    );

    if (!mounted) return null;
    return ReactDOM.createPortal(drawer, document.body);
  },
);

Drawer.displayName = 'Drawer';
